 98	/// One-way tag rule: metadata MAY exist without codebase tags;
 99	/// if tagged in code, MUST exist in metadata.
100	pub fn check_one_way_tags<S, T>(metadata_ids: &[S], tagged_ids: &[T]) -> Result<()>
101	where
102	    S: AsRef<str>,
103	    T: AsRef<str>,
104	{
105	    let meta: HashSet<String> = metadata_ids
106	        .iter()
107	        .map(|s| s.as_ref().to_string())
108	        .collect();
109	    let mut missing = Vec::new();
110	    for id in tagged_ids {
111	        let id = id.as_ref();
112	        if !meta.contains(id) {
113	            missing.push(id.to_string());
114	        }
115	    }
116	    if missing.is_empty() {
117	        Ok(())
118	    } else {
119	        bail!(
120	            "tagged in code but missing from metadata: {}",
121	            missing.join(", ")
122	        )
123	    }
124	}
