  2	//! post-commit mirrors branch-mode metadata edits into the resolved sidecar branch.
  3	//!
  4	//! Hooks are installed as marked blocks so residual can coexist with other tools that
  5	//! also hook the same file (e.g. Entire CLI's post-commit checkpoint condenser):
  6	//! foreign content is preserved and residual's block appended after it; a prior
  7	//! residual-owned block (same marker) is replaced in place on reinstall.
  8	
  9	use anyhow::{Context, Result};
 10	
 11	pub fn install() -> Result<()> {
 12	    let git_hooks_dir = find_git_hooks_dir()?;
 13	
 14	    let pre_commit_body = r#"# residual pre-commit hook — validates residual/ data before commit
 15	#
 16	# Hard block: residual metadata must live on the git-sidecar branch, never on the
 17	# working branch — except residual/config.toml, the in-repo pointer file. This check
 18	# has no override flag by design.
 19	WRITE_AUTH=$(git diff --cached --name-only | grep '^residual/\.residual-write-authorized$')
 20	if [ -n "$WRITE_AUTH" ]; then
 21	  echo "residual: refusing commit — the local write-authorization marker must remain unstaged:" >&2
 22	  echo "$WRITE_AUTH" | sed 's/^/  /' >&2
 23	  echo "Unstage it with: git restore --staged residual/.residual-write-authorized" >&2
 24	  exit 1
 25	fi
 26	
 27	LEAKED=$(git diff --cached --name-only | grep '^residual/' | grep -v '^residual/config\.toml$')
 28	if [ -n "$LEAKED" ]; then
 29	  echo "residual: refusing commit — residual metadata staged on the working branch (belongs on the git-sidecar branch):" >&2
 30	  echo "$LEAKED" | sed 's/^/  /' >&2
 31	  echo "Unstage with: git restore --staged <path>" >&2
 32	  exit 1
 33	fi
 34	
 35	STAGED=$(git diff --cached --name-only | grep '^residual/')
 36	
 37	if [ -z "$STAGED" ]; then
 38	  STRICT=$(residual config 2>/dev/null | grep 'strict' | awk '{print $3}')
 39	  [ "$STRICT" = "false" ] && exit 0
 40	fi
 41	
 42	residual verify all || exit 1
 43	residual verify walk-reminder --staged || exit 1
 44	"#;
 45	
 46	    let commit_msg_body = r#"# residual commit-msg hook — lexicon/component vocabulary (warn by default)
 47	residual verify commit-msg "$1" --staged || exit 1
 48	"#;
 49	
 50	    let post_commit_body = r#"# residual post-commit hook — mirrors hand-edited metadata (via `residual branch edit`)
 51	# into the resolved metadata branch, tagging the commit with this commit's title+hash.
 52	# Silent no-op when there's nothing to sync (most branches never touch residual data).
 53	residual branch sync-commit >/dev/null 2>&1 || true
 54	"#;
 55	
 56	    let pre_commit = git_hooks_dir.join("pre-commit");
 57	    let commit_msg = git_hooks_dir.join("commit-msg");
 58	    let post_commit = git_hooks_dir.join("post-commit");
 59	
 60	    write_hook(&pre_commit, "pre-commit", pre_commit_body)?;
 61	    write_hook(&commit_msg, "commit-msg", commit_msg_body)?;
 62	    write_hook(&post_commit, "post-commit", post_commit_body)?;
 63	
 64	    println!("Installed pre-commit hook to {}", pre_commit.display());
 65	    println!("Installed commit-msg hook to {} (warn by default; set commit_msg_enforce = true in residual/config.toml to block)", commit_msg.display());
 66	    println!("Installed post-commit hook to {}", post_commit.display());
 67	    Ok(())
 68	}
