 70	fn find_git_hooks_dir() -> Result<std::path::PathBuf> {
 71	    let cwd = std::env::current_dir().context("failed to get current directory")?;
 72	    let mut dir = cwd.as_path();
 73	    loop {
 74	        let candidate = dir.join(".git/hooks");
 75	        if candidate.is_dir() {
 76	            return Ok(candidate);
 77	        }
 78	        match dir.parent() {
 79	            Some(parent) => dir = parent,
 80	            None => anyhow::bail!("could not find .git/hooks directory (not a git repository?)"),
 81	        }
 82	    }
 83	}
 84	
 85	fn marker_begin(name: &str) -> String {
 86	    format!("# >>> residual:{name} >>>")
 87	}
 88	
 89	fn marker_end(name: &str) -> String {
 90	    format!("# <<< residual:{name} <<<")
 91	}
 92	
 93	/// Merge `body` into `existing` hook content under a marked block for `name`: replaces
 94	/// a prior residual block in place (reinstall), or appends after foreign content
 95	/// (first install alongside another tool's hook), or writes a fresh file with shebang.
 96	fn merge_hook_content(existing: Option<String>, name: &str, body: &str) -> String {
 97	    let begin = marker_begin(name);
 98	    let end = marker_end(name);
 99	    let block = format!("{begin}\n{body}{end}\n");
100	
101	    match existing {
102	        None => format!("#!/bin/sh\n{block}"),
103	        Some(mut content) => match (content.find(&begin), content.find(&end)) {
104	            (Some(b), Some(e)) => {
105	                let e_end = e + end.len();
106	                content.replace_range(b..e_end, block.trim_end());
107	                content
108	            }
109	            _ => {
110	                if !content.ends_with('\n') {
111	                    content.push('\n');
112	                }
113	                content.push_str(&block);
114	                content
115	            }
116	        },
117	    }
118	}
119	
120	fn write_hook(path: &std::path::Path, name: &str, body: &str) -> Result<()> {
121	    let existing = std::fs::read_to_string(path).ok();
122	    let mut content = merge_hook_content(existing, name, body);
123	    // Portable shebang for nix sandboxes (no /usr/bin/env → bash).
124	    content = match content.find('\n') {
125	        Some(i) if content[..i].contains("/usr/bin/env") || content[..i].starts_with("#!") => {
126	            format!("#!/bin/sh\n{}", &content[i + 1..])
127	        }
128	        _ if !content.starts_with("#!") => format!("#!/bin/sh\n{content}"),
129	        _ => content,
130	    };
131	    std::fs::write(path, content)
132	        .with_context(|| format!("failed to write hook to {}", path.display()))?;
133	
134	    #[cfg(unix)]
135	    {
136	        use std::os::unix::fs::PermissionsExt;
137	        let mut perms = std::fs::metadata(path)?.permissions();
138	        perms.set_mode(0o755);
139	        std::fs::set_permissions(path, perms)
140	            .with_context(|| format!("failed to set permissions on {}", path.display()))?;
141	    }
142	
143	    Ok(())
144	}
